<?php
declare(strict_types=1);
require_once __DIR__.'/credential_helpers.php';
requirePermission('credentials','view');
$view=(string)($_GET['view']??'active');if(!in_array($view,['active','employees'],true)){http_response_code(404);exit('Details page not found');}
$pdo=db();[$scope,$scopeParams]=credentialScopeSql('c');$safe=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$q=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$perPage=50;$pageTitle=$view==='active'?'Active credentials':'Employees with credentials';
if($view==='active'){
 $filter=$scope;$params=$scopeParams;if($q!==''){$filter.=' AND (c.service_name LIKE ? OR c.credential_username LIKE ? OR e.full_name LIKE ? OR si.software_name LIKE ?)';array_push($params,...array_fill(0,4,'%'.$q.'%'));}
 $count=$pdo->prepare('SELECT COUNT(*) FROM credentials c LEFT JOIN employees e ON e.id=c.employee_id LEFT JOIN software_installations si ON si.id=c.software_installation_id WHERE c.active=1 AND '.$filter);$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$stmt=$pdo->prepare('SELECT c.id,c.service_name,c.credential_username,e.full_name employee_name,e.employee_id employee_code,si.software_name FROM credentials c LEFT JOIN employees e ON e.id=c.employee_id LEFT JOIN software_installations si ON si.id=c.software_installation_id WHERE c.active=1 AND '.$filter.' ORDER BY c.service_name,c.id LIMIT '.$perPage.' OFFSET '.(($page-1)*$perPage));$stmt->execute($params);$rows=$stmt->fetchAll();
}else{
 $employeeScope=canAdmin()?'1=1':"(c.user_id=? OR EXISTS(SELECT 1 FROM credential_department_access cda JOIN credential_departments cd ON cd.id=cda.department_id JOIN employees ce ON ce.id=c.employee_id WHERE cda.user_id=? AND LOWER(TRIM(cd.name))=LOWER(TRIM(ce.department))))";$ep=canAdmin()?[]:[(int)currentUser()['id'],(int)currentUser()['id']];$filter=$employeeScope;$params=$ep;if($q!==''){$filter.=' AND (e.full_name LIKE ? OR e.employee_id LIKE ?)';array_push($params,'%'.$q.'%','%'.$q.'%');}
 $sql=' FROM employees e JOIN credentials c ON c.employee_id=e.id AND c.active=1 WHERE '.$filter.' GROUP BY e.id,e.employee_id,e.full_name';$count=$pdo->prepare('SELECT COUNT(*) FROM (SELECT e.id'.$sql.') scoped_employees');$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$stmt=$pdo->prepare('SELECT e.id,e.employee_id,e.full_name,COUNT(c.id) credential_count'.$sql.' ORDER BY e.full_name,e.id LIMIT '.$perPage.' OFFSET '.(($page-1)*$perPage));$stmt->execute($params);$rows=$stmt->fetchAll();
}
require __DIR__.'/header.php';
?>
<section class="category-detail-section credentials-page"><div class="category-detail-heading"><div><div class="eyebrow">AUTHORIZED CREDENTIALS</div><h2><?=$safe($pageTitle)?></h2></div><div class="drilldown-nav"><a class="btn" href="dashboard.php">Back to Dashboard</a><a class="btn" href="credentials.php">Credentials</a></div></div>
<form method="get" class="toolbar"><input type="hidden" name="view" value="<?=$safe($view)?>"><label for="credential-dashboard-search">Search</label><input id="credential-dashboard-search" name="q" value="<?=$safe($q)?>" placeholder="<?=$view==='active'?'Service, username, employee or software':'Employee name or ID'?>"><button class="btn" type="submit">Search</button></form><p class="muted">Showing <?=count($rows)?> of <?=$total?> records · page <?=$page?> of <?=$pages?></p>
<div class="table-scroll"><table><thead><?php if($view==='active'):?><tr><th>Service</th><th>Username</th><th>Linked employee</th><th>Employee ID</th><th>Software</th></tr><?php else:?><tr><th>Employee</th><th>Employee ID</th><th>Active credential count</th><th>Profile</th></tr><?php endif;?></thead><tbody>
<?php foreach($rows as $r):if($view==='active'):?><tr><td><?=$safe($r['service_name'])?></td><td><?=$safe($r['credential_username']?:'—')?></td><td><?=$safe($r['employee_name']?:'—')?></td><td><?=$safe($r['employee_code']?:'—')?></td><td><?=$safe($r['software_name']?:'—')?></td></tr><?php else:?><tr><td><?=$safe($r['full_name'])?></td><td><?=$safe($r['employee_id'])?></td><td><?=number_format((int)$r['credential_count'])?></td><td><a class="btn" href="employee.php?id=<?=(int)$r['id']?>">Employee profile</a></td></tr><?php endif;endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty-state">No authorized credential records found.</td></tr><?php endif;?></tbody></table></div>
<nav class="pagination" aria-label="Pages"><?php for($n=1;$n<=$pages;$n++):$link=$_GET;$link['page']=$n;?><a class="btn" href="?<?=http_build_query($link)?>" <?=$n===$page?'aria-current="page"':''?>><?=$n?></a><?php endfor;?></nav></section><?php require __DIR__.'/footer.php'; ?>
